const urls = ["mk-39874.mp4","mk-39878.mp4","mk-1261.mp4"].map(n=>`http://localhost:8899/${n}`);
const results = await Promise.all(urls.map(u => new Promise(res => {
  const v = document.createElement("video");
  v.preload = "metadata"; v.muted = true;
  v.onloadedmetadata = () => res({u: u.split("/").pop(), w: v.videoWidth, h: v.videoHeight, dur: Math.round(v.duration*10)/10});
  v.onerror = () => res({u: u.split("/").pop(), error: true});
  v.src = u;
  setTimeout(()=>res({u: u.split("/").pop(), timeout: true}), 8000);
})));
nodeRepl.write(JSON.stringify(results, null, 2));

